def classify_substance(pH):
    if pH < 7:
        return "Acid"
    elif pH > 7:
        return "Base"
    else:
        return "Neutral"

# Example usage:
print(classify_substance(3))  # Output: Acid
print(classify_substance(10)) # Output: Base
print(classify_substance(7))  # Output: Neutral
